onChange.script:
	def unwrapDeep(v):
		v = unwrap(v)
		if hasattr(v, 'items'): return {k: unwrapDeep(val) for k, val in v.items()}
		if isinstance(v, list): return [unwrapDeep(x) for x in v]
		return v

	def unwrap(v):
		while hasattr(v, 'value'):
			v = v.value
		return v

	def normalizeAttr(attributeName, attr):

		attr = unwrap(attr)
		if not hasattr(attr, 'get'): return attr
		if attributeName == '_ProductionDay': return {'startTime': int(unwrap(attr.get('startTime')) or 0), 'endTime': int(unwrap(attr.get('endTime')) or 0)}
		elif attributeName == '_oeeThreshold':
			return {
				'oee': float(unwrap(attr.get('oee')) or 0.6),
				'a': float(unwrap(attr.get('a')) or 0.8),
				'p': float(unwrap(attr.get('p')) or 0.8),
				'q': float(unwrap(attr.get('q')) or 0.8),
				'oeeTolerance': float(unwrap(attr.get('oeeTolerance')) or 0.1),
				'aTolerance': float(unwrap(attr.get('aTolerance')) or 0.1),
				'pTolerance': float(unwrap(attr.get('pTolerance')) or 0.1),
				'qTolerance': float(unwrap(attr.get('qTolerance')) or 0.1)
			}

		else: return unwrapDeep(attr.get('value'))

	def valuesEqual(a, b):
		return system.util.jsonEncode(a) == system.util.jsonEncode(b)

	system.perspective.print("attribute binding change %s"%origin)
	if not origin in ('BindingWriteback', 'Script'): return

	assetId = self.custom.assets.selectedAssetInfo.assetId
	if assetId is None: return

	userId = self.session.custom.kanoa.security.userId

	oldAttrs = previousValue.value or {}
	newAttrs = currentValue.value or {}

	count = 0
	msgs = []

	for attributeName, newAttr in newAttrs.items():
		newAttr = unwrapDeep(newAttr)
		oldAttr = unwrapDeep(oldAttrs.get(attributeName)) if hasattr(oldAttrs, 'get') else {}

		if not hasattr(newAttr, 'get'):
			system.perspective.print("Skipping %s because newAttr is not a dict. Type=%s Value=%s" % (attributeName, type(newAttr), newAttr))
			continue

		if not hasattr(oldAttr, 'get'): oldAttr = {}

		newValue = normalizeAttr(attributeName, newAttr)
		oldValue = normalizeAttr(attributeName, oldAttr)

		newInherited = bool(unwrapDeep(newAttr.get('inherited', False)))
		oldInherited = bool(unwrapDeep(oldAttr.get('inherited', False))) if hasattr(oldAttr, 'get') else False

		assetAttrId = newAttr.get('assetAttrId') or oldAttr.get('assetAttrId')

		system.perspective.print("%s old=%s new=%s equal=%s" % (attributeName, oldValue, newValue, valuesEqual(newValue, oldValue)))
		system.perspective.print("%s oldInherited=%s newInherited=%s oldAttrId=%s newAttrId=%s" % (
			attributeName,
			oldInherited,
			newInherited,
			oldAttr.get('assetAttrId') if hasattr(oldAttr, 'get') else None,
			newAttr.get('assetAttrId') if hasattr(newAttr, 'get') else None
		))

		# A value changed while inherited (the checkboxes stay enabled) becomes the asset's own
		if newInherited and oldInherited and origin == 'BindingWriteback' and not valuesEqual(newValue, oldValue): newInherited = False

		if newInherited and assetAttrId:
			system.perspective.print("Calling deleteAssetAttribute() with %s"%assetAttrId)
			retVal = system.kanoa.asset.deleteAssetAttribute(assetAttrId, userId)
			if retVal: count += 1
			continue

		if newInherited:
			system.perspective.print("newInherited skipping")
			continue

		if valuesEqual(newValue, oldValue) and newInherited == oldInherited: 
			system.perspective.print("valuesEqual skipping")
			continue

		# normalize booleans
		if isinstance(newValue, bool): encodedValue = int(newValue)   # → 0 / 1 (recommended for DB)
		else: encodedValue = system.util.jsonEncode(newValue)

#		encodedValue = system.util.jsonEncode(unwrapDeep(newValue))

		assetAttributeId, msg = system.kanoa.asset.addAssetAttribute(assetId, attributeName, encodedValue, userId)
		system.perspective.print("addAssetAttribute() returned %s %s. Called with %s %s %s %s"%(assetAttributeId, msg, assetId, attributeName, encodedValue, userId))		

		count += 1

	if count:
		# One toast however many are saved in a row: update it while it's showing, show it (ignored while showing) once it's gone
		toast = {'id': 'assetAttributeSaved', 'type': 'success', 'message': "Attribute saved"}
		system.kanoa.toast.update(toast)
		system.kanoa.toast.show(toast)
	self.refreshBinding("custom.assetAttributes")

	return

