assetId = self.view.custom.assets.selectedAssetInfo.assetId
parentId = self.view.custom.assets.selectedAssetInfo.parentId
if assetId is None: return
parentPath = system.kanoa.utilities.getFieldValue('assetPath', system.kanoa.asset.getAssets({'assetId': self.view.custom.assets.selectedAssetInfo.parentId}))

system.perspective.print("duplicateAsset() called for %s"%assetId)
self.view.custom.info = {"showBar": True, "text": "Creating assets", "type": "INFO"}

retVal, msg = system.kanoa.asset.copyAsset(assetId, self.session.custom.kanoa.security.userId)
self.updateSortOrder(parentId)

if msg: system.kanoa.toast.show({'type': 'warning', 'message': 'Unable to copy asset. %s'%msg})
else: system.kanoa.toast.show({'type': 'success', 'message': 'Asset copied'})	

self.view.custom.info = {"showBar": False, "text": "", "type": "INFO"}

self.view.refreshBinding("custom.assets.data")

return

system.perspective.print("selectAsset() called with %s"%assetId)
if assetId is None: self.view.refreshBinding("custom.assets.selectedAssetInfo")
else:
	self.view.custom.assets.selectedAssetInfo = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.asset.getAssets({'assetId': assetId}), 0)

return

assetInfo = dict(self.view.custom.assets.selectedAssetInfo)
assetId = assetInfo['assetId']
userId = self.session.custom.kanoa.security.userId

system.perspective.print("saveAsset() called for assetId %s"%assetId)

# Uses tooling is applied around the save: turned off before it (the database needs OEE Enabled for it), on after it
wantTooling = bool(assetInfo.get('usesTooling')) and bool(assetInfo['oeeEnabled']) and not assetInfo.get('isTooling')
hadTooling = False
if assetId is not None:
	current = system.kanoa.asset.getAssets({'assetId': assetId})
	hadTooling = current.rowCount > 0 and bool(current.getValueAt(0, 'usesTooling'))
if hadTooling and not wantTooling:
	result, msg = system.kanoa.tooling.setUsesTooling(assetId, False, userId)
	if msg:
		system.kanoa.toast.show({'type': 'error', 'message': 'Unable to save asset. %s' % msg})
		return
if assetId is None:
	if system.kanoa.asset.getAssets({'assetPath': (self.view.custom.assets.selectedAssetInfo.assetPath or '') + '\\' + assetInfo['assetName']}).rowCount > 0:
		system.kanoa.toast.show({'type': 'warning', 'message': 'This asset already exists'})
		return

	assetId, msg = system.kanoa.asset.addAsset(assetInfo, userId)
else:
	retVal, msg = system.kanoa.asset.updateAsset(assetInfo, userId)

if msg:
	system.kanoa.toast.show({'type': 'error', 'message': 'Unable to save asset. %s'%msg})
	return

#What didn't save goes in the one toast at the end (868mvvzbz)
problems = []
if wantTooling and not hadTooling:
	result, msg = system.kanoa.tooling.setUsesTooling(assetId, True, userId)
	if msg: problems.append("tooling couldn't be turned on: %s" % msg)

if assetInfo['oeeEnabled']: #We'll add some default modes and states if they don't exist
	if system.kanoa.asset.getAssetModes({'assetId': assetId}).rowCount == 0:
		modes = system.kanoa.utilities.convertDatasetToDict(system.kanoa.asset.getModes({'reservedBySystem': True}), 'modeName', 'modeId')
		self.view.custom.info = {"showBar": True, "text": "Linking %s with default modes"%(assetInfo['assetName']), "type": "INFO"}	
		system.kanoa.asset.linkAssetModes([assetId], list(modes.values()), userId, list(modes.values()))

	if system.kanoa.asset.getAssetStates({'assetId': assetId}).rowCount == 0:
		#Tool statuses (state type Tooling) are reserved too, but they're linked to tools only (ToolLifeService), and Unknown State only
		#to a code recorded with no link (StateEventService, 868mw5ug5)
		states = dict((row['stateName'], row['stateId']) for row in system.kanoa.utilities.convertDatasetToJSON(system.kanoa.asset.getStates({'reservedBySystem': True})) if row['stateTypeName'] != 'Tooling' and row['stateName'] != 'Unknown State')
		self.view.custom.info = {"showBar": True, "text": "Linking %s with default states"%(assetInfo['assetName']), "type": "INFO"}
		system.kanoa.asset.linkAssetStates([assetId], list(states.values()), userId, list(states.values()))

self.view.custom.info = {"showBar": False, "text": "", "type": "INFO"}				

changed, failures = self.saveAssetAttributes(assetId)
problems += failures

self.view.custom.assets.selectedAssetInfo.assetId = assetId
#One toast for the save, with an id per asset so saves in quick succession show one
name = assetInfo['assetName']
if problems: system.kanoa.toast.show({'id': 'assetSaved-%s' % assetId, 'type': 'warning', 'message': 'Asset "%s" saved, but %s' % (name, '; '.join(problems))})
else: system.kanoa.toast.show({'id': 'assetSaved-%s' % assetId, 'type': 'success', 'message': 'Asset "%s" saved' % name})

#Reload the saved asset without clearing it first: a refreshBinding of selectedAssetInfo (a blank asset) lands after this and empties the form
self.view.refreshBinding("custom.assets.data")
self.selectAsset(assetId)	

#A new asset is selected in the tree too: it kept the parent selected, so clicking the parent again to add another did nothing (868mu1f7z)
if assetInfo['assetId'] is None:
	assetPath = self.view.custom.assets.selectedAssetInfo.assetPath
	if assetPath: system.perspective.sendMessage('setTreeSelection', {'msgHandler': 'assetSelected', 'ids': [assetPath]})

return


